/* PaKuWord – polska paczka dzienna 2026-11-27: nowa dziedzina Astronomia (30) + 30 haseł w istniejących dziedzinach (his, mat, arc, cook, art) */
window.PW_CONTENT = window.PW_CONTENT || {};
window.PW_CONTENT.pl = (window.PW_CONTENT.pl || []).concat([
/* ---------- ASTRONOMIA ---------- */
{id:"ast_astronomy",cat:"ast",t:"Astronomia",
 s:"Nauka o gwiazdach, planetach, galaktykach i wszystkim, co znajduje się poza atmosferą Ziemi.",
 l:"Astronomowie obserwują niebo gołym okiem, przez teleskopy, anteny radiowe i sondy kosmiczne, a potem za pomocą fizyki i matematyki ustalają, z czego zbudowane są ciała niebieskie, jak daleko się znajdują i jak się zmieniają. To jedna z najstarszych nauk, bo ludzie od zawsze układali kalendarze i wyznaczali drogę według Słońca, Księżyca i gwiazd. Astronomii nie należy mylić z astrologią, która twierdzi, że położenie planet wpływa na charakter i los człowieka – nauka nie potwierdza tych twierdzeń.",
 x:"Zapisała się do szkolnego koła astronomicznego i już wie, jak znaleźć wieczorem Saturna.",
 f:"Nazwa pochodzi od greckich słów astron, czyli gwiazda, i nomos, czyli prawo lub porządek.",
 js:"Nauka o gwiazdach, planetach i kosmosie.",
 jl:"Astronomia bada wszystko, co jest na niebie i daleko za nim: Słońce, Księżyc, planety, gwiazdy i ogromne gromady gwiazd. Astronomowie używają teleskopów i sprytnej matematyki, żeby sprawdzić, jak duże i jak odległe są te obiekty oraz z czego są zrobione.",
 jx:"Do projektu z astronomii Kuba przez cały miesiąc co wieczór rysował Księżyc."},
{id:"ast_planet",cat:"ast",t:"Planeta",
 s:"Duże, kuliste ciało krążące wokół gwiazdy, które oczyściło swoją orbitę z innych obiektów.",
 l:"W Układzie Słonecznym jest osiem planet. Cztery najbliższe Słońcu – Merkury, Wenus, Ziemia i Mars – są małe i skaliste. Cztery dalsze – Jowisz, Saturn, Uran i Neptun – są znacznie większe i zbudowane głównie z gazów lub lodów. Planeta nie świeci własnym światłem jak gwiazda; widzimy ją, bo odbija światło Słońca. Dlatego w teleskopie Wenus ma fazy, tak jak Księżyc.",
 x:"Ta jasna kropka obok Księżyca to nie gwiazda, tylko planeta Jowisz.",
 f:"Słowo planeta pochodzi od greckiego wyrazu oznaczającego wędrowca, bo dawni obserwatorzy zauważyli, że kilka jasnych punktów powoli przesuwa się na tle nieruchomych gwiazd.",
 js:"Duży, okrągły świat, który krąży wokół gwiazdy.",
 jl:"Ziemia jest planetą, tak samo jak Mars, Jowisz i jeszcze pięć innych. Wszystkie krążą wokół Słońca po wielkich pętlach. Planety same nie świecą. Wydają się jasne, bo odbija się od nich światło Słońca, trochę jak od lustra.",
 jx:"Zosia zapamiętała kolejność planet dzięki zabawnemu zdaniu, którego nauczyła ją pani."},
{id:"ast_dwarf_planet",cat:"ast",t:"Planeta karłowata",
 s:"Kuliste ciało krążące wokół Słońca, które nie oczyściło swojego otoczenia z innych obiektów, więc nie jest pełnoprawną planetą.",
 l:"W 2006 roku Międzynarodowa Unia Astronomiczna przyjęła definicję: planeta krąży wokół Słońca, ma dość dużą masę, by własna grawitacja nadała jej kulisty kształt, i oczyściła swoją orbitę z innych podobnych ciał. Planeta karłowata spełnia dwa pierwsze warunki, ale nie trzeci, bo dzieli swój obszar z wieloma innymi obiektami. Pluton, który porusza się wśród niezliczonych lodowych ciał za Neptunem, stał się więc planetą karłowatą – podobnie jak Ceres w pasie planetoid i Eris.",
 x:"Dziadek wciąż nazywa Plutona dziewiątą planetą, ale w moim podręczniku to planeta karłowata.",
 f:"Ceres odkrył w 1801 roku włoski astronom Giuseppe Piazzi; najpierw nazywano ją planetą, potem planetoidą, a od 2006 roku planetą karłowatą.",
 js:"Mały, okrągły świat, który nie jest do końca prawdziwą planetą.",
 jl:"Pluton jest okrągły i krąży wokół Słońca, zupełnie jak planeta. Ale mieszka w zatłoczonej okolicy pełnej innych lodowych skał. Naukowcy uznali, że prawdziwa planeta musi rządzić na swojej drodze, dlatego Plutona nazywamy teraz planetą karłowatą.",
 jx:"W klasie głosowaliśmy, czy Pluton powinien być planetą, i wygrała drużyna planety karłowatej."},
{id:"ast_exoplanet",cat:"ast",t:"Planeta pozasłoneczna (egzoplaneta)",
 s:"Planeta krążąca wokół innej gwiazdy niż Słońce.",
 l:"Egzoplanety są tak odległe i tak słabo widoczne obok swoich gwiazd, że rzadko udaje się je zobaczyć bezpośrednio. Zwykle wykrywa się je pośrednio: gwiazda nieco przygasa, gdy planeta przechodzi przed jej tarczą, albo lekko się chybocze, bo przyciąga ją grawitacja planety. Znamy już tysiące egzoplanet. Są wśród nich gazowe olbrzymy krążące bardzo blisko gwiazd i skaliste globy w strefie, w której mogłaby istnieć woda w stanie ciekłym – dlatego tak ciekawią badaczy szukających życia.",
 x:"Teleskop kosmiczny zbadał światło gwiazdy, żeby ustalić, z czego składa się atmosfera egzoplanety.",
 f:"Pierwsze potwierdzone planety poza Układem Słonecznym ogłosili w 1992 roku polski astronom Aleksander Wolszczan i Dale Frail; krążą wokół pulsara, czyli martwej, szybko wirującej gwiazdy.",
 js:"Planeta, która krąży wokół dalekiej gwiazdy, a nie wokół naszego Słońca.",
 jl:"Nasze Słońce jest gwiazdą, a na nocnym niebie są tysiące innych gwiazd. Wiele z nich też ma swoje planety. Takie dalekie planety nazywamy egzoplanetami. Nie da się do nich polecieć, ale naukowcy je wykrywają, bo gwiazda leciutko przygasa, kiedy planeta przesuwa się przed nią.",
 jx:"Antek wyobrażał sobie, jak to jest oglądać dwa zachody słońca na egzoplanecie z dwiema gwiazdami."},
{id:"ast_orbit",cat:"ast",t:"Orbita",
 s:"Zakrzywiony tor, po którym jedno ciało w kosmosie porusza się wokół drugiego pod wpływem grawitacji.",
 l:"Księżyc krąży po orbicie wokół Ziemi, a Ziemia wokół Słońca. Ciało na orbicie bardzo szybko pędzi w bok, a grawitacja nieustannie ciągnie je do środka, więc zamiast odlecieć albo spaść prosto w dół, wciąż jakby spada dookoła większego ciała. Orbity nie są idealnymi okręgami, lecz lekko spłaszczonymi elipsami. Czas jednego pełnego okrążenia to okres orbitalny – dla Ziemi wokół Słońca wynosi on rok.",
 x:"Satelita potrzebuje około półtorej godziny, żeby okrążyć Ziemię.",
 f:"Na początku siedemnastego wieku Johannes Kepler wykazał, że planety poruszają się po elipsach, a nie po okręgach, i że bliżej Słońca pędzą szybciej.",
 js:"Droga, po której coś w kosmosie krąży dookoła czegoś innego.",
 jl:"Przywiąż piłeczkę do sznurka i zakręć nią nad głową. Sznurek ciągnie piłkę do środka, więc ta lata w kółko. W kosmosie nie ma sznurka, ale tę samą pracę wykonuje grawitacja. Dlatego Księżyc ciągle krąży wokół Ziemi. Jego droga to orbita.",
 jx:"Na plakacie kropkowana linia pokazuje orbitę każdej planety wokół Słońca."},
{id:"ast_light_year",cat:"ast",t:"Rok świetlny",
 s:"Odległość, jaką światło pokonuje w ciągu roku; służy do mierzenia ogromnych odległości w kosmosie.",
 l:"Światło jest najszybsze ze wszystkiego – w ciągu sekundy pokonuje prawie trzysta tysięcy kilometrów. W ciągu roku przebywa około dziewięciu i pół biliona kilometrów i właśnie ta odległość to jeden rok świetlny. Mimo nazwy rok świetlny jest miarą odległości, a nie czasu. Ponieważ światło potrzebuje czasu, by do nas dotrzeć, patrząc na odległe obiekty, patrzymy w przeszłość: widzimy gwiazdę taką, jaka była, gdy wyruszyło z niej światło.",
 x:"Najbliższa Słońcu gwiazda leży nieco ponad cztery lata świetlne od nas.",
 f:"Światło Słońca biegnie do Ziemi około ośmiu minut, więc gdyby Słońce nagle zniknęło, zauważylibyśmy to dopiero po mniej więcej ośmiu minutach.",
 js:"Odległość, jaką światło przebywa w ciągu całego roku.",
 jl:"Światło jest niesamowicie szybkie. W jedną sekundę mogłoby okrążyć Ziemię ponad siedem razy! Wyobraź sobie, jak daleko dociera w ciągu całego roku. Ta olbrzymia odległość to rok świetlny. Naukowcy jej używają, bo gwiazdy są zbyt daleko, by mierzyć je w kilometrach.",
 jx:"Ola nie mogła uwierzyć, że gwiazda, na którą patrzy, wysłała swoje światło, zanim ona się urodziła."},
{id:"ast_constellation",cat:"ast",t:"Gwiazdozbiór (konstelacja)",
 s:"Grupa gwiazd, w której ludzie dopatrzyli się obrazu, oraz otaczający ją obszar nieba.",
 l:"Dawno temu ludzie łączyli jasne gwiazdy wyobrażonymi liniami w postacie – myśliwego, lwa czy łabędzia – i opowiadali o nich historie. Dziś astronomowie dzielą całe niebo na osiemdziesiąt osiem oficjalnych gwiazdozbiorów o ustalonych granicach, trochę jak państwa na mapie, tak że każda gwiazda należy do dokładnie jednego. Gwiazdy jednego gwiazdozbioru tylko z Ziemi wydają się bliskie; w rzeczywistości jedne mogą być dużo dalej od innych.",
 x:"Orion to jeden z najłatwiejszych do odnalezienia gwiazdozbiorów w zimowy wieczór.",
 f:"Wiele używanych dziś nazw gwiazdozbiorów pochodzi z listy czterdziestu ośmiu konstelacji opisanych w drugim wieku przez greckiego astronoma Ptolemeusza.",
 js:"Obrazek ułożony z gwiazd na niebie.",
 jl:"Jeśli spojrzysz na gwiazdy jak na rysowankę „połącz kropki”, zobaczysz kształty: myśliwego, wielką niedźwiedzicę albo łabędzia. Ludzie wymyślili te obrazki tysiące lat temu i opowiadali o nich legendy. Każdy taki obrazek to gwiazdozbiór.",
 jx:"Dziadek pokazał mi gwiazdozbiór Łabędzia, który leci wzdłuż Drogi Mlecznej."},
{id:"ast_galaxy",cat:"ast",t:"Galaktyka",
 s:"Ogromny układ gwiazd, gazu i pyłu utrzymywany razem przez grawitację.",
 l:"Galaktyki mogą liczyć miliony, a nawet setki miliardów gwiazd. Niektóre są płaskimi spiralami z wygiętymi ramionami, inne mają gładki, owalny kształt, a jeszcze inne są nieregularnymi obłokami. Nasza Galaktyka, Droga Mleczna, jest spiralna. Galaktyki dzielą olbrzymie, niemal puste przestrzenie, a same często skupiają się w grupy i gromady. Większość z nich jest tak daleko, że nawet w dobrym teleskopie wyglądają jak blade plamki.",
 x:"W ciemną jesienną noc Galaktykę Andromedy widać bez teleskopu jako słabą, rozmytą plamkę.",
 f:"Słowo galaktyka pochodzi od greckiego słowa oznaczającego mleko – stąd też nazwa naszej Galaktyki, Droga Mleczna.",
 js:"Olbrzymia rodzina miliardów gwiazd w kosmosie.",
 jl:"Gwiazdy nie są rozrzucone w kosmosie byle jak. Mieszkają razem w ogromnych grupach zwanych galaktykami. Nasze Słońce należy do galaktyki o nazwie Droga Mleczna, w której są miliardy gwiazd. A w kosmosie jest jeszcze mnóstwo innych galaktyk.",
 jx:"Hania namalowała na ścianie w swoim pokoju fioletową, wirującą galaktykę."},
{id:"ast_milky_way",cat:"ast",t:"Droga Mleczna",
 s:"Spiralna galaktyka, do której należy Słońce; z Ziemi widać ją jako jasną smugę na nocnym niebie.",
 l:"Żyjemy wewnątrz Drogi Mlecznej, w spokojnej okolicy mniej więcej w połowie drogi między jej środkiem a brzegiem. Ponieważ patrzymy na dysk Galaktyki od środka, wygląda on jak długa, mglista rzeka światła. Teleskop pokazuje, że ta poświata składa się z niezliczonych gwiazd zbyt słabych, by dostrzec je pojedynczo. W centrum Drogi Mlecznej znajduje się bardzo masywna czarna dziura. Miejskie światła zasłaniają Drogę Mleczną, więc wiele osób nigdy jej nie widziało.",
 x:"Daleko od miasta leżeliśmy na trawie i patrzyliśmy, jak Droga Mleczna rozciąga się nad jeziorem.",
 f:"Słońce potrzebuje mniej więcej dwustu trzydziestu milionów lat, by raz okrążyć środek Drogi Mlecznej.",
 js:"Nasza galaktyka, która wygląda jak mleczna smuga na nocnym niebie.",
 jl:"W bardzo ciemną noc, daleko od latarni, widać na niebie bladą, mglistą smugę. Ta smuga składa się z milionów gwiazd. To nasza Galaktyka, Droga Mleczna, a nasze Słońce jest jedną z jej gwiazd.",
 jx:"Na biwaku nie było lamp, więc wreszcie zobaczyliśmy Drogę Mleczną."},
{id:"ast_nebula",cat:"ast",t:"Mgławica",
 s:"Ogromny obłok gazu i pyłu w kosmosie, w którym mogą rodzić się gwiazdy albo który odrzuciła umierająca gwiazda.",
 l:"Niektóre mgławice jasno świecą, bo gorące, młode gwiazdy w ich wnętrzu pobudzają gaz do świecenia. Inne są ciemne i zasłaniają gwiazdy leżące za nimi. W gęstych mgławicach grawitacja powoli zbiera gaz, aż rodzą się nowe gwiazdy, dlatego nazywa się je czasem gwiezdnymi żłobkami. Inne mgławice to rozszerzające się szczątki starych gwiazd. Kolorowe zdjęcia kosmosu, które oglądamy w internecie, to często mgławice fotografowane przez wiele godzin przez specjalne filtry.",
 x:"Mgławicę w Orionie widać jako małą, mglistą plamkę w miejscu miecza Oriona.",
 f:"Łacińskie słowo nebula oznacza mgłę albo chmurę.",
 js:"Olbrzymia, kolorowa chmura w kosmosie, w której rodzą się gwiazdy.",
 jl:"Mgławica to gigantyczna chmura gazu i pyłu unosząca się w kosmosie. W niektórych mgławicach gaz powoli się zgęszcza i zapalają się nowe gwiazdy. Dlatego naukowcy nazywają je gwiezdnymi żłobkami. Zdjęcia mgławic to jedne z najpiękniejszych obrazów kosmosu.",
 jx:"Ulubiony plakat Stasia przedstawia różowo-niebieską mgławicę pełną małych gwiazd."},
{id:"ast_supernova",cat:"ast",t:"Supernowa",
 s:"Gigantyczny wybuch gwiazdy, który przez krótki czas może świecić jaśniej niż cała galaktyka.",
 l:"Supernowa wybucha, gdy bardzo masywnej gwieździe kończy się paliwo i jej jądro się zapada albo gdy mała martwa gwiazda, zwana białym karłem, ściąga za dużo materii od sąsiadki. Eksplozja rozrzuca zewnętrzne warstwy gwiazdy w przestrzeń. Te obłoki niosą pierwiastki powstałe we wnętrzach gwiazd, takie jak tlen, wapń i żelazo, które później wchodzą w skład nowych gwiazd i planet. Żelazo w naszej krwi powstało kiedyś w gwiazdach i zostało rozsiane przez takie wybuchy.",
 x:"Astronomowie zauważyli nowy punkt światła w odległej galaktyce i potwierdzili, że to supernowa.",
 f:"W 1054 roku chińscy astronomowie zapisali pojawienie się nowej gwiazdy tak jasnej, że przez kilka tygodni była widoczna w dzień; jej pozostałością jest Mgławica Krab.",
 js:"Superjasny wybuch olbrzymiej gwiazdy.",
 jl:"Bardzo duże gwiazdy nie gasną po cichu. Kiedy kończy im się paliwo, wybuchają tak jasno, że mogą przyćmić miliardy innych gwiazd. To supernowa. Wybuch rozrzuca w kosmos gwiezdny materiał, a część z niego trafia do nowych planet, a nawet do ludzi.",
 jx:"Pani powiedziała, że żelazo w naszych ciałach powstało dawno temu w supernowej."},
{id:"ast_black_hole",cat:"ast",t:"Czarna dziura",
 s:"Obszar przestrzeni, w którym materia jest tak ściśnięta, że jej grawitacja nie wypuszcza niczego, nawet światła.",
 l:"Czarna dziura może powstać, gdy bardzo masywna gwiazda zapada się pod koniec życia. Jej granicę nazywamy horyzontem zdarzeń: cokolwiek go przekroczy, nie może już wrócić. Czarnych dziur nie widać bezpośrednio, ale astronomowie wykrywają je po tym, jak przyciągają pobliskie gwiazdy, i po gorącym, świecącym gazie, który wiruje wokół nich. Olbrzymie czarne dziury, miliony lub miliardy razy cięższe od Słońca, znajdują się w centrach większości dużych galaktyk, także naszej.",
 x:"Film dokumentalny pokazywał, jak czarna dziura zagina światło gwiazd leżących za nią.",
 f:"W 2019 roku Teleskop Horyzontu Zdarzeń, czyli sieć radioteleskopów na całym świecie, pokazał pierwszy obraz cienia czarnej dziury w galaktyce M87.",
 js:"Miejsce w kosmosie, które przyciąga tak mocno, że nawet światło nie może uciec.",
 jl:"Czarna dziura może zostać po olbrzymiej gwieździe, która ścisnęła się w malutką przestrzeń. Przyciąga tak mocno, że nic, co podleci za blisko, nie ucieknie – nawet światło. Dlatego jest zupełnie czarna. Nie martw się: w pobliżu Ziemi nie ma żadnej czarnej dziury.",
 jx:"Szymon zrobił model czarnej dziury z lejka i wirującego brokatu."},
{id:"ast_pulsar",cat:"ast",t:"Pulsar",
 s:"Szybko wirująca martwa gwiazda, która wysyła wiązki fal radiowych odbierane na Ziemi jako regularne impulsy.",
 l:"Gdy masywna gwiazda wybucha, jej jądro może zostać ściśnięte w gwiazdę neutronową: kulę o średnicy około dwudziestu kilometrów, ale cięższą od Słońca. Niektóre gwiazdy neutronowe obracają się wiele razy na sekundę i wysyłają wiązki promieniowania ze swoich biegunów magnetycznych. Jeśli wiązka omiata Ziemię, przy każdym obrocie odbieramy impuls, jak błysk latarni morskiej. Pulsary „tykają” tak równo, że astronomowie używają ich jako niezwykle dokładnych zegarów.",
 x:"Radioteleskop odebrał rytm pulsara, równy jak metronom.",
 f:"Pierwszego pulsara odkryła w 1967 roku Jocelyn Bell Burnell, doktorantka z Cambridge, która zauważyła dziwny, regularny sygnał w danych z radioteleskopu.",
 js:"Malutka wirująca gwiazda, która błyska jak latarnia morska.",
 jl:"Kiedy olbrzymia gwiazda wybucha, może zostawić po sobie małą, superciężką kulkę, która kręci się bardzo szybko. Kręcąc się, wysyła promienie jak latarnia morska. Za każdym razem, gdy promień trafia w Ziemię, nasze teleskopy słyszą krótkie „pyk”. Taka wirująca gwiazda to pulsar.",
 jx:"Słuchaliśmy nagrania pulsara i brzmiało jak tykający zegar."},
{id:"ast_comet",cat:"ast",t:"Kometa",
 s:"Niewielkie lodowe ciało, któremu w pobliżu Słońca wyrastają świecąca głowa i długie warkocze.",
 l:"Stałe jądro komety to bryła lodu, pyłu i skał, często o średnicy zaledwie kilku kilometrów. Daleko od Słońca jest zamarznięte i ciemne. Gdy kometa zbliża się do Słońca, lód zamienia się w gaz, który wyrywa się razem z pyłem i tworzy mglistą otoczkę zwaną komą. Światło i strumień cząstek ze Słońca wypychają ten materiał w warkocze, które zawsze są skierowane od Słońca, niezależnie od tego, w którą stronę leci kometa.",
 x:"Na zdjęciu warkocz komety rozciąga się nad górami.",
 f:"Kometa Halleya wraca mniej więcej co siedemdziesiąt pięć, siedemdziesiąt sześć lat; ostatnio widziano ją w 1986 roku, a następny raz pojawi się w 2061 roku.",
 js:"Wielka, brudna śnieżka w kosmosie, której przy Słońcu wyrasta świecący ogon.",
 jl:"Kometa jest jak olbrzymia kula śniegu zmieszanego z pyłem i kamieniami. Krąży wokół Słońca po bardzo długiej drodze. Kiedy zbliża się do Słońca, ogrzewa się, a z niej wylatują gaz i pył. Tworzy się świecący warkocz, który może mieć miliony kilometrów długości.",
 jx:"Babcia widziała kometę Halleya, kiedy była młoda, a ja mam nadzieję zobaczyć ją, kiedy będę starszy."},
{id:"ast_meteor",cat:"ast",t:"Meteor",
 s:"Świetlna smuga na niebie, powstająca, gdy mały okruch skały kosmicznej lub pyłu spala się w atmosferze Ziemi.",
 l:"Trzy podobne słowa łatwo pomylić. Meteoroid to mały kamyk albo pyłek pędzący przez kosmos. Gdy z ogromną prędkością wpada w atmosferę, powietrze przed nim tak się nagrzewa, że świeci – i ten błysk to meteor, potocznie zwany spadającą gwiazdą. Jeśli kawałek przetrwa i spadnie na ziemię, nazywamy go meteorytem. Roje meteorów pojawiają się, gdy Ziemia przechodzi przez smugę pyłu pozostawioną przez kometę.",
 x:"W sierpniu siedzieliśmy do późna i w godzinę naliczyliśmy dwadzieścia meteorów.",
 f:"Rój Perseidów, który co roku osiąga maksimum około połowy sierpnia, pochodzi z pyłu pozostawionego przez kometę Swift–Tuttle; w Polsce nazywa się go też łzami świętego Wawrzyńca.",
 js:"Spadająca gwiazda, czyli kosmiczny pyłek, który spala się na niebie.",
 jl:"Spadająca gwiazda wcale nie jest gwiazdą. To malutki kamyczek z kosmosu, często mniejszy od ziarnka grochu, który wpada w powietrze wokół Ziemi. Leci tak szybko, że się rozgrzewa i świeci, zostawiając na sekundę jasną kreskę na niebie. Kawałek, który spadnie na ziemię, to meteoryt.",
 jx:"Lena zobaczyła meteor na niebie i szybko pomyślała życzenie."},
{id:"ast_asteroid",cat:"ast",t:"Planetoida (asteroida)",
 s:"Skaliste lub metaliczne ciało mniejsze od planety, które krąży wokół Słońca.",
 l:"Większość planetoid Układu Słonecznego krąży w pasie planetoid między Marsem a Jowiszem. Mają rozmiary od głazów po ciała szerokie na setki kilometrów, a większość ma nieregularny kształt, trochę jak ziemniaki. To pozostałości z czasów, gdy powstawały planety, więc ich badanie pomaga zrozumieć młody Układ Słoneczny. Astronomowie śledzą planetoidy zbliżające się do Ziemi, a w 2022 roku sonda DART celowo uderzyła w jedną z nich, by sprawdzić, czy da się zmienić jej tor.",
 x:"Sonda kosmiczna pobrała z powierzchni planetoidy maleńką próbkę pyłu.",
 f:"Wbrew temu, co pokazują filmy, pas planetoid to głównie pusta przestrzeń; sondy przelatują przez niego bez omijania skał.",
 js:"Duża kosmiczna skała, która krąży wokół Słońca.",
 jl:"Planetoidy to skały, które zostały z czasów, gdy bardzo dawno temu powstawały planety. Niektóre są małe jak samochód, a inne wielkie jak cały kraj. Większość krąży wokół Słońca w szerokim pierścieniu między Marsem a Jowiszem, który nazywamy pasem planetoid.",
 jx:"W naszej grze statek kosmiczny musiał bezpiecznie ominąć planetoidę."},
{id:"ast_eclipse",cat:"ast",t:"Zaćmienie",
 s:"Zjawisko, w którym jedno ciało niebieskie zasłania światło docierające do innego, na przykład gdy Księżyc zakrywa Słońce.",
 l:"Podczas zaćmienia Słońca Księżyc przechodzi między Słońcem a Ziemią i zakrywa część tarczy słonecznej albo całą – ale tylko dla ludzi na wąskim pasie Ziemi. W czasie całkowitego zaćmienia niebo ciemnieje i widać bladą zewnętrzną atmosferę Słońca, czyli koronę. Podczas zaćmienia Księżyca na Księżyc pada cień Ziemi, a tarcza często robi się miedzianoczerwona. Na Słońce nigdy nie wolno patrzeć bezpośrednio, nawet gdy jest częściowo zakryte – potrzebne są specjalne okulary albo metody pośrednie.",
 x:"Oglądaliśmy z balkonu zaćmienie Księżyca, a jego tarcza powoli robiła się czerwona.",
 f:"Całkowite zaćmienia Słońca są możliwe, bo Słońce jest około czterystu razy szersze od Księżyca, ale też około czterystu razy dalej, więc na niebie oba wydają się prawie tej samej wielkości.",
 js:"Kiedy Księżyc zasłania Słońce albo cień Ziemi pada na Księżyc.",
 jl:"Czasem Słońce, Ziemia i Księżyc ustawiają się w jednej linii. Jeśli Księżyc znajdzie się między nami a Słońcem, zasłania je na kilka minut i robi się ciemno. To zaćmienie Słońca. Jeśli cień Ziemi padnie na Księżyc, Księżyc może świecić na czerwono. To zaćmienie Księżyca. Nigdy nie patrz prosto w Słońce!",
 jx:"Zrobiliśmy z pudełka po płatkach przeglądarkę otworkową, żeby bezpiecznie oglądać zaćmienie."},
{id:"ast_moon_phases",cat:"ast",t:"Fazy Księżyca",
 s:"Zmieniające się w ciągu miesiąca kształty oświetlonej części Księżyca widzianej z Ziemi.",
 l:"Księżyc nie świeci sam; zawsze połowa jego powierzchni jest oświetlona przez Słońce. Gdy krąży wokół Ziemi, widzimy różną część tej oświetlonej połowy. Podczas nowiu oświetlona strona jest odwrócona od nas i Księżyca prawie nie widać. Potem przybywa go przez sierp i pierwszą kwadrę aż do pełni, a później znów ubywa. Cały cykl trwa około dwudziestu dziewięciu i pół dnia. Fazy nie powstają z powodu cienia Ziemi.",
 x:"Kalendarz na lodówce pokazuje fazę Księżyca na każdy dzień miesiąca.",
 f:"Po polsku Księżyc nazywano dawniej miesiącem, i stąd wzięła się nazwa jednostki czasu – miesiąc to mniej więcej jeden cykl faz Księżyca.",
 js:"Różne kształty, jakie Księżyc wydaje się mieć w ciągu miesiąca.",
 jl:"Czasem Księżyc wygląda jak cienki uśmiech, czasem jak pół ciasteczka, a czasem jak okrągły talerz. Tak naprawdę Księżyc nie zmienia kształtu. Po prostu widzimy większą albo mniejszą część jego słonecznej strony, kiedy krąży wokół Ziemi. Te kształty to fazy Księżyca.",
 jx:"Adaś prowadził księżycowy dzienniczek i zobaczył, jak sierp rośnie aż do pełni."},
{id:"ast_equinox",cat:"ast",t:"Równonoc",
 s:"Jeden z dwóch dni w roku, w marcu i we wrześniu, gdy dzień i noc na całym świecie trwają prawie tyle samo.",
 l:"Oś Ziemi jest nachylona. W czasie równonocy ani północna, ani południowa półkula nie jest przechylona w stronę Słońca, więc Słońce wschodzi prawie dokładnie na wschodzie i zachodzi prawie dokładnie na zachodzie. Równonoc marcowa, około dwudziestego marca, rozpoczyna astronomiczną wiosnę na półkuli północnej i jesień na południowej. Równonoc wrześniowa, około dwudziestego drugiego lub dwudziestego trzeciego września, działa odwrotnie. Dzień i noc są wtedy zbliżone, ale ze względu na sposób liczenia wschodu Słońca dzień jest zwykle o kilka minut dłuższy.",
 x:"W dniu równonocy zmierzyliśmy w południe nasze cienie i porównaliśmy je z czerwcowymi.",
 f:"Łacińska nazwa aequinoctium, od której pochodzą nazwy równonocy w wielu językach, oznacza równą noc.",
 js:"Dzień wiosną albo jesienią, kiedy dzień i noc są prawie tak samo długie.",
 jl:"Dwa razy w roku, w marcu i we wrześniu, dzień i noc trwają prawie tyle samo, mniej więcej po dwanaście godzin. Te dni nazywamy równonocą. Po marcowej równonocy dni w Polsce stają się dłuższe od nocy.",
 jx:"W pierwszy dzień wiosny cała klasa posadziła nasiona słonecznika."},
{id:"ast_solstice",cat:"ast",t:"Przesilenie",
 s:"Dzień w roku z najdłuższym albo najkrótszym dniem, w czerwcu i w grudniu.",
 l:"Ponieważ oś Ziemi jest nachylona, wysokość Słońca w południe zmienia się w ciągu roku. Podczas przesilenia czerwcowego, około dwudziestego pierwszego czerwca, półkula północna jest najbardziej zwrócona ku Słońcu – ma wtedy najdłuższy dzień i najkrótszą noc, a półkula południowa najkrótszy dzień. W czasie przesilenia grudniowego, około dwudziestego pierwszego lub dwudziestego drugiego grudnia, jest odwrotnie. Po przesileniu zimowym dni zaczynają się powoli wydłużać, co wiele kultur świętowało.",
 x:"W dniu przesilenia letniego było jeszcze jasno, kiedy szliśmy spać.",
 f:"W wielu językach nazwa przesilenia pochodzi od łacińskiego solstitium, czyli „Słońce staje”, bo w tych dniach wysokość Słońca w południe na chwilę przestaje się zmieniać, zanim zawróci.",
 js:"Najdłuższy albo najkrótszy dzień w roku.",
 jl:"W czerwcu jest jeden dzień, kiedy Słońce świeci najdłużej, a w grudniu dzień, kiedy zachodzi najwcześniej. Te wyjątkowe dni to przesilenia. Po najkrótszym dniu w grudniu każdy kolejny dzień jest odrobinę jaśniejszy.",
 jx:"W dniu przesilenia zjedliśmy kolację na dworze i oglądaliśmy bardzo późny zachód słońca."},
{id:"ast_telescope",cat:"ast",t:"Teleskop",
 s:"Przyrząd, który zbiera światło lub inne promieniowanie z odległych obiektów, by wyglądały na jaśniejsze, większe i wyraźniejsze.",
 l:"Teleskop soczewkowy, czyli refraktor, załamuje i skupia światło szklanymi soczewkami, a teleskop zwierciadlany, czyli reflektor, używa wklęsłych luster. Najważniejsza jest średnica głównej soczewki lub lustra: im większa, tym więcej światła zbiera i tym słabsze obiekty pokazuje. Niektóre teleskopy w ogóle nie korzystają ze światła widzialnego. Radioteleskopy to olbrzymie czasze, a teleskopy kosmiczne krążą nad atmosferą, która rozmywa i pochłania część światła, by obserwować podczerwień, ultrafiolet albo promieniowanie rentgenowskie.",
 x:"Przez teleskop pierścienie Saturna wyglądały jak malutki, idealny owal.",
 f:"Isaac Newton zbudował około 1668 roku jeden z pierwszych działających teleskopów zwierciadlanych, używając wklęsłego metalowego lustra zamiast soczewki.",
 js:"Rura z soczewkami albo lustrami, przez którą dalekie rzeczy wyglądają na bliższe.",
 jl:"Teleskop jest jak olbrzymie oko, które zbiera dużo światła. Dzięki niemu łatwiej zobaczyć kratery na Księżycu, pierścienie Saturna i dalekie gwiazdy. Niektóre teleskopy są tak wielkie, że mają własny budynek, a niektóre latają nawet w kosmosie.",
 jx:"Dziadek ustawił teleskop w ogrodzie, żebyśmy mogli obejrzeć kratery na Księżycu."},
{id:"ast_space_station",cat:"ast",t:"Międzynarodowa Stacja Kosmiczna",
 s:"Duże laboratorium krążące wokół Ziemi, w którym mieszkają i pracują astronauci z wielu krajów.",
 l:"Międzynarodowa Stacja Kosmiczna, w skrócie nazywana ISS, była budowana na orbicie kawałek po kawałku od 1998 roku przez agencje kosmiczne między innymi Stanów Zjednoczonych, Rosji, Europy, Japonii i Kanady. Okrąża Ziemię około szesnastu razy na dobę na wysokości około czterystu kilometrów. Załoga bada, jak nieważkość wpływa na ludzki organizm, rośliny i materiały, co pomaga przygotować dłuższe podróże kosmiczne. Z Ziemi stację widać jako jasny, nieruchomo świecący punkt, który szybko przesuwa się po niebie.",
 x:"Sprawdziliśmy w internecie, kiedy stacja kosmiczna przeleci nad naszym miastem.",
 f:"Ludzie mieszkają na pokładzie stacji nieprzerwanie od listopada 2000 roku.",
 js:"Wielkie latające laboratorium, w którym wysoko nad Ziemią mieszkają astronauci.",
 jl:"Wysoko ponad chmurami wokół Ziemi lata ogromna stacja. Mieszkają w niej przez wiele miesięcy astronauci z różnych krajów. Unoszą się w powietrzu, śpią w śpiworach przypiętych do ścian i robią naukowe doświadczenia. W pogodny wieczór można czasem zobaczyć stację jako jasną, sunącą kropkę.",
 jx:"Franek pomachał stacji kosmicznej, kiedy przelatywała nad naszym domem."},
{id:"ast_aurora",cat:"ast",t:"Zorza polarna",
 s:"Falujące zasłony kolorowego światła na nocnym niebie, powstające, gdy cząstki ze Słońca uderzają w górne warstwy atmosfery.",
 l:"Słońce nieustannie wysyła strumień naładowanych cząstek, zwany wiatrem słonecznym. Pole magnetyczne Ziemi kieruje część z nich w okolice biegunów, gdzie zderzają się wysoko w atmosferze z tlenem i azotem i pobudzają je do świecenia – najczęściej na zielono, czasem na czerwono lub fioletowo. Na północy mówimy o zorzy północnej, a na południu o zorzy południowej. Po silnych wybuchach na Słońcu zorzę można zobaczyć znacznie dalej od biegunów niż zwykle, czasem nawet w Polsce.",
 x:"W Norwegii staliśmy w śniegu i patrzyliśmy, jak zielone światła tańczą nad fiordem.",
 f:"Łacińska nazwa zorzy północnej, aurora borealis, łączy imię rzymskiej bogini jutrzenki Aurory ze słowem oznaczającym północny.",
 js:"Piękne świecące kolory, które tańczą na niebie blisko bieguna północnego i południowego.",
 jl:"Daleko na północy i na południu nocne niebo czasem wypełniają falujące wstęgi zielonego i różowego światła. Dzieje się tak, gdy malutkie cząstki ze Słońca zderzają się z powietrzem wysoko nad Ziemią i sprawiają, że ono świeci. To zorza polarna.",
 jx:"Marzeniem Mai jest pojechać na Islandię i zobaczyć zorzę polarną."},
{id:"ast_light_pollution",cat:"ast",t:"Zanieczyszczenie światłem",
 s:"Nadmiar sztucznego światła w nocy, który rozjaśnia niebo i zasłania gwiazdy.",
 l:"Latarnie, ekrany reklamowe i oświetlone budynki kierują dużo światła w górę i na boki, tam, gdzie nie jest potrzebne. Przez to niebo nad miastami świeci na pomarańczowo lub szaro, a widać tylko najjaśniejsze gwiazdy. Zanieczyszczenie światłem dezorientuje też zwierzęta: ptaki wędrowne, ćmy i nietoperze. Marnuje również energię. Proste rozwiązania to osłonięte lampy świecące w dół, cieplejsza barwa światła i wyłączanie lamp, z których nikt nie korzysta.",
 x:"Przez zanieczyszczenie światłem z naszego miejskiego mieszkania widać tylko kilka gwiazd.",
 f:"W Polsce działają parki ciemnego nieba, na przykład w Bieszczadach i Izerach, gdzie ogranicza się sztuczne oświetlenie, by nadal można było podziwiać Drogę Mleczną.",
 js:"Gdy w nocy jest tyle świateł, że nie widać gwiazd.",
 jl:"W dużych miastach przez całą noc świecą latarnie, reklamy i okna. Całe to światło ucieka w niebo i zasłania gwiazdy. Może też mylić zwierzęta, które potrzebują ciemności, takie jak ćmy, nietoperze i sowy. Ten kłopot nazywamy zanieczyszczeniem światłem.",
 jx:"Nasza szkoła wyłącza nocą lampy na boisku, żeby ograniczyć zanieczyszczenie światłem."},
{id:"ast_big_bang",cat:"ast",t:"Wielki Wybuch",
 s:"Teoria naukowa, według której Wszechświat zaczął się około trzynastu i ośmiu dziesiątych miliarda lat temu w niezwykle gorącym i gęstym stanie i od tamtej pory się rozszerza.",
 l:"Teoria Wielkiego Wybuchu nie opisuje eksplozji w jednym miejscu, lecz rozciąganie się całej przestrzeni z bardzo gorącego i ściśniętego początku. Gdy Wszechświat się rozszerzał i stygł, powstały pierwsze atomy, a potem gwiazdy i galaktyki. Teorię potwierdza kilka rodzajów dowodów: galaktyki oddalają się od siebie, całe niebo słabo świeci resztkami ciepła, zwanymi mikrofalowym promieniowaniem tła, a ilości najlżejszych pierwiastków zgadzają się z przewidywaniami.",
 x:"Na lekcji przyrody zrobiliśmy oś czasu Wszechświata, zaczynając od Wielkiego Wybuchu.",
 f:"Angielskiej nazwy Big Bang użył w 1949 roku w audycji radiowej BBC astronom Fred Hoyle, który sam w tę teorię nie wierzył.",
 js:"Naukowe wyjaśnienie, jak bardzo, bardzo dawno temu zaczął się Wszechświat.",
 jl:"Naukowcy uważają, że dawno, dawno temu wszystko, co jest we Wszechświecie, było ściśnięte razem i niezwykle gorące. Potem zaczęło się rozszerzać i rozszerza się do dziś. Powoli powstały gwiazdy, galaktyki i planety. Ten początek nazywamy Wielkim Wybuchem.",
 jx:"Nadmuchaliśmy balon z kropkami, żeby zobaczyć, jak galaktyki oddalają się po Wielkim Wybuchu."},
{id:"ast_redshift",cat:"ast",t:"Przesunięcie ku czerwieni",
 s:"Rozciągnięcie światła obiektu, który się od nas oddala, przesuwające jego barwy w stronę czerwonego końca widma.",
 l:"Gdy źródło światła się oddala, jego fale świetlne są rozciągane, więc stają się dłuższe i bardziej czerwone. Podobnie dzieje się z dźwiękiem: syrena karetki brzmi niżej, kiedy karetka odjeżdża. Rozszczepiając światło galaktyki na widmo, astronomowie mierzą, o ile przesunęły się jego charakterystyczne linie. Prawie wszystkie odległe galaktyki wykazują przesunięcie ku czerwieni, i to tym większe, im są dalej. To jeden z głównych dowodów na to, że Wszechświat się rozszerza.",
 x:"Przesunięcie ku czerwieni zdradziło naukowcom, że galaktyka jest miliardy lat świetlnych od nas.",
 f:"Georges Lemaître zaproponował w 1927 roku, że Wszechświat się rozszerza, a Edwin Hubble opublikował obserwacje w 1929 roku; w 2018 roku astronomowie zalecili nazywać tę zależność prawem Hubble’a–Lemaître’a.",
 js:"Gdy światło rzeczy, które od nas uciekają, wygląda na trochę bardziej czerwone.",
 jl:"Czy zauważyłeś, że syrena karetki brzmi niżej, kiedy karetka odjeżdża? Ze światłem dzieje się coś podobnego. Kiedy galaktyka się od nas oddala, jej światło jest odrobinę bardziej czerwone. Dzięki temu naukowcy wiedzą, że galaktyki od siebie uciekają.",
 jx:"Pani pokazała nam na sprężynce, jak fale się rozciągają przy przesunięciu ku czerwieni."},
{id:"ast_pl_wielki_woz",cat:"ast",only:1,t:"Wielki Wóz",
 s:"Polska nazwa siedmiu jasnych gwiazd w gwiazdozbiorze Wielkiej Niedźwiedzicy, układających się w kształt wozu z dyszlem.",
 l:"Wielki Wóz nie jest osobnym gwiazdozbiorem, lecz charakterystycznym układem gwiazd, czyli asteryzmem, w Wielkiej Niedźwiedzicy. Cztery gwiazdy tworzą skrzynię wozu, a trzy jego dyszel. Z Polski Wielki Wóz nigdy nie zachodzi, więc można go zobaczyć w każdą pogodną noc przez cały rok. Jeśli przedłużysz linię łączącą dwie tylne gwiazdy skrzyni mniej więcej pięć razy, trafisz na Gwiazdę Polarną, która wskazuje północ.",
 x:"Na obozie harcerskim tata nauczył mnie szukać Gwiazdy Polarnej dzięki Wielkiemu Wozowi.",
 f:"Gwiazda Polarna leży na końcu dyszla Małego Wozu, mniejszego i słabiej świecącego układu w Małej Niedźwiedzicy.",
 js:"Siedem jasnych gwiazd, które układają się w kształt wozu albo rondelka.",
 jl:"Jeśli w pogodną noc spojrzysz na północ, znajdziesz siedem jasnych gwiazd ułożonych jak wóz z długim dyszlem albo rondelek z rączką. To Wielki Wóz. Dwie jego gwiazdy wskazują drogę do Gwiazdy Polarnej, która pomagała podróżnym nie zgubić drogi.",
 jx:"Julka pierwsza znalazła Wielki Wóz, a potem po jego gwiazdach trafiła do Gwiazdy Polarnej."},
{id:"ast_pl_frombork",cat:"ast",only:1,t:"Frombork",
 s:"Miasteczko nad Zalewem Wiślanym, w którym przez wiele lat żył i pracował Mikołaj Kopernik.",
 l:"Mikołaj Kopernik był kanonikiem kapituły warmińskiej i przez dużą część dorosłego życia mieszkał we Fromborku, przy wzgórzu katedralnym. Tu prowadził obserwacje nieba i pracował nad dziełem „O obrotach sfer niebieskich”, wydanym w 1543 roku, w roku jego śmierci. Pochowano go w tutejszej katedrze. Dziś na wzgórzu działa Muzeum Mikołaja Kopernika, a w dawnej wieży można zobaczyć wahadło Foucaulta, które pokazuje obrót Ziemi.",
 x:"Na wycieczce do Fromborka oglądaliśmy wahadło, które powoli zmienia kierunek, bo Ziemia się obraca.",
 f:"W 2008 roku naukowcy potwierdzili, że szczątki odnalezione w katedrze należą do Kopernika, porównując DNA z włosami z książki, której używał; w 2010 roku pochowano go tam ponownie.",
 js:"Miasteczko, w którym mieszkał i badał niebo Mikołaj Kopernik.",
 jl:"Frombork to małe miasteczko nad wodą, na północy Polski. Na wzgórzu stoi tam stara katedra. Właśnie tu przez wiele lat mieszkał Mikołaj Kopernik, patrzył w gwiazdy i pisał swoją słynną książkę o tym, że Ziemia krąży wokół Słońca.",
 jx:"We Fromborku wspięliśmy się na wieżę i zobaczyliśmy z góry cały Zalew Wiślany."},
{id:"ast_pl_heweliusz",cat:"ast",only:1,t:"Jan Heweliusz",
 s:"Gdański astronom z siedemnastego wieku, autor jednej z pierwszych szczegółowych map Księżyca.",
 l:"Jan Heweliusz żył w latach 1611–1687. Był piwowarem i rajcą Gdańska, a jednocześnie jednym z najwybitniejszych obserwatorów nieba swoich czasów. Na dachach swoich kamienic zbudował obserwatorium z instrumentami, które sam projektował. W 1647 roku wydał „Selenografię”, dzieło z dokładnymi mapami Księżyca. Sporządził też wielki katalog gwiazd. Pomagała mu żona, Elżbieta Heweliusz, którą uważa się za jedną z pierwszych kobiet astronomów; to ona wydała po jego śmierci jego atlas nieba.",
 x:"W Gdańsku stoi pomnik Jana Heweliusza, który patrzy w niebo.",
 f:"Heweliusz wprowadził kilka gwiazdozbiorów używanych do dziś, na przykład Tarczę, którą nazwał na cześć króla Jana Trzeciego Sobieskiego, a także Jaszczurkę i Rysia.",
 js:"Astronom z Gdańska, który ponad trzysta lat temu narysował mapy Księżyca.",
 jl:"Jan Heweliusz mieszkał w Gdańsku dawno temu. W dzień warzył piwo i zajmował się sprawami miasta, a w nocy wychodził na dach swojego domu i patrzył w gwiazdy. Narysował bardzo dokładne mapy Księżyca. Pomagała mu w tym jego żona Elżbieta.",
 jx:"Na lekcji Kasia narysowała Księżyc tak dokładnie jak Heweliusz."},
{id:"ast_pl_hermaszewski",cat:"ast",only:1,t:"Mirosław Hermaszewski",
 s:"Pilot wojskowy, który w 1978 roku jako pierwszy Polak poleciał w kosmos.",
 l:"Mirosław Hermaszewski urodził się w 1941 roku i był pilotem Wojska Polskiego. Wybrano go do programu Interkosmos, w którym kraje bloku wschodniego wysyłały swoich kosmonautów na radzieckie stacje. Dwudziestego siódmego czerwca 1978 roku wystartował statkiem Sojuz 30 razem z Piotrem Klimukiem i spędził na orbicie około ośmiu dni, w tym na stacji Salut 6, gdzie prowadził doświadczenia naukowe. Zmarł w 2022 roku.",
 x:"W szkole nazwanej imieniem Hermaszewskiego wisi zdjęcie startu rakiety z 1978 roku.",
 f:"Przez prawie pięćdziesiąt lat był jedynym Polakiem, który był w kosmosie; drugim został w 2025 roku Sławosz Uznański-Wiśniewski, który poleciał na Międzynarodową Stację Kosmiczną.",
 js:"Pierwszy Polak, który poleciał w kosmos.",
 jl:"Mirosław Hermaszewski był pilotem samolotów. W 1978 roku wsiadł do statku kosmicznego i poleciał w kosmos. Przez około osiem dni krążył wokół Ziemi, robił doświadczenia i patrzył na naszą planetę z góry. Był pierwszym Polakiem w kosmosie.",
 jx:"Staś chce zostać astronautą, tak jak Mirosław Hermaszewski."},
/* ---------- HISTORIA (+6) ---------- */
{id:"his_antiquity",cat:"his",t:"Starożytność",
 s:"Długi okres dziejów przed średniowieczem, zwłaszcza czasy starożytnej Grecji i Rzymu.",
 l:"Historycy często mówią o antyku, czyli starożytności klasycznej, gdy chodzi o stulecia, w których wokół Morza Śródziemnego rozkwitały cywilizacje grecka i rzymska – mniej więcej od ósmego wieku przed naszą erą do piątego wieku naszej ery. W szerszym znaczeniu starożytność obejmuje też inne dawne cywilizacje, takie jak Egipt, Mezopotamia, Indie czy Chiny. Z tych czasów pochodzi wiele rzeczy, z których korzystamy do dziś: demokracja, teatr, geometria, prawo rzymskie i alfabet łaciński.",
 x:"W sali starożytności w muzeum są greckie wazy i rzymskie monety.",
 f:"Wielu historyków za koniec starożytności na Zachodzie uznaje rok 476, gdy odsunięto od władzy ostatniego cesarza zachodniorzymskiego.",
 js:"Czasy dawnych ludów, takich jak Grecy, Rzymianie i Egipcjanie.",
 jl:"Starożytność to bardzo dawne czasy, sprzed tysięcy lat. To czasy piramid w Egipcie, igrzysk olimpijskich w Grecji i rzymskich cesarzy. Wiele rzeczy, z których korzystamy do dziś, na przykład teatr i litery naszego alfabetu, zaczęło się właśnie wtedy.",
 jx:"Na lekcji o starożytności zrobiliśmy z kartonu rzymskie tarcze."},
{id:"his_crusades",cat:"his",t:"Wyprawy krzyżowe",
 s:"Seria wojen religijnych, głównie od jedenastego do trzynastego wieku, w których chrześcijańskie wojska z Europy walczyły o Jerozolimę i inne ziemie.",
 l:"Pierwszą krucjatę ogłosił papież Urban Drugi w 1095 roku, a jej uczestnicy zdobyli Jerozolimę w 1099 roku. W ciągu kolejnych dwóch stuleci odbyły się następne wyprawy, a państwa założone przez krzyżowców na Bliskim Wschodzie w końcu upadły. Krucjaty przyniosły wiele cierpienia, w tym napaści na muzułmanów, Żydów i chrześcijan Wschodu, ale ożywiły też handel oraz wymianę towarów i wiedzy między Europą a Bliskim Wschodem. Historycy wciąż spierają się o ich przyczyny i znaczenie.",
 x:"Zamek, który zwiedzaliśmy w Syrii, zbudowali krzyżowcy w dwunastym wieku.",
 f:"Nazwa pochodzi od krzyża, który uczestnicy wypraw naszywali na swoje ubrania.",
 js:"Długie wojny w średniowieczu, gdy wojska z Europy wyruszały walczyć o Jerozolimę.",
 jl:"Około tysiąca lat temu królowie i rycerze z Europy wyruszali w długie podróże na Bliski Wschód, żeby walczyć o Jerozolimę – miasto święte dla chrześcijan, muzułmanów i Żydów. Te wojny nazywamy wyprawami krzyżowymi. Wielu ludzi cierpiało, ale ludzie też ze sobą handlowali i uczyli się od siebie.",
 jx:"W książce rycerz miał na tunice czerwony krzyż, bo wyruszał na wyprawę krzyżową."},
{id:"his_hanseatic",cat:"his",t:"Hanza",
 s:"Potężny średniowieczny związek miast kupieckich nad Bałtykiem i Morzem Północnym, który chronił i kontrolował handel.",
 l:"Od trzynastego do piętnastego wieku kupcy i miasta północnej Europy łączyli się w Hanzę, by chronić statki przed piratami, zdobywać przywileje handlowe i rozstrzygać spory. Przewodziła jej Lubeka, a członkami były między innymi Hamburg, Brema, Ryga, Gdańsk, Toruń, Elbląg i Kraków. Hanza miała faktorie handlowe aż w Londynie, Bergen i Nowogrodzie i handlowała rybami, zbożem, drewnem, futrami, woskiem i suknem. Stopniowo traciła znaczenie, gdy rosły silne państwa i otwierały się nowe szlaki morskie.",
 x:"Wysokie ceglane spichlerze nad portem pochodzą z czasów, gdy miasto należało do Hanzy.",
 f:"Gdańsk zawdzięczał Hanzie i handlowi zbożem z Polski swoje bogactwo, a jego słynny żuraw portowy służył do przeładunku towarów i stawiania masztów na statkach.",
 js:"Duży klub miast handlowych nad morzem w średniowieczu.",
 jl:"Dawno temu kupcy z miast nad Bałtykiem i Morzem Północnym się umówili: będą sobie pomagać i się chronić. Ich statki woziły ryby, drewno i futra z miasta do miasta. Tę wielką drużynę miast nazywano Hanzą. Należał do niej także Gdańsk.",
 jx:"W muzeum w Gdańsku oglądaliśmy model hanzeatyckiego statku handlowego."},
{id:"his_age_of_discovery",cat:"his",t:"Wielkie odkrycia geograficzne",
 s:"Okres od piętnastego do siedemnastego wieku, gdy europejscy żeglarze odkrywali drogi morskie do Afryki, Azji i Ameryki.",
 l:"Pierwsi byli Portugalczycy i Hiszpanie, którym pomagały lepsze statki, kompasy i mapy. Krzysztof Kolumb dotarł na Karaiby w 1492 roku, Vasco da Gama opłynął Afrykę i dotarł do Indii w 1498 roku, a wyprawa rozpoczęta przez Ferdynanda Magellana jako pierwsza opłynęła świat w 1522 roku. Te podróże połączyły kontynenty i zmieniły handel, kuchnię i naukę, ale wielu ludom przyniosły podbój, zabójcze choroby i niewolnictwo. Dlatego dziś zwraca się uwagę, że „odkryte” lądy od dawna zamieszkiwali ludzie.",
 x:"W atlasie zaznaczono trasy słynnych wypraw z czasów wielkich odkryć geograficznych.",
 f:"Magellan zginął na Filipinach w 1521 roku, więc pierwszą podróż dookoła świata ukończył Juan Sebastián Elcano na jedynym ocalałym statku, „Victorii”.",
 js:"Czasy, gdy żeglarze z Europy przepływali oceany, szukając nowych lądów i dróg.",
 jl:"Około pięciuset lat temu żeglarze z Europy wyruszyli drewnianymi statkami przez ogromne oceany. Chcieli znaleźć nowe drogi po przyprawy i złoto. Dotarli do lądów, których wcześniej nie znali, ale tam już mieszkali ludzie, a dla nich przybycie Europejczyków często było nieszczęściem.",
 jx:"Do projektu o wielkich odkryciach Ania zrobiła kompas z korka i igły."},
{id:"his_berlin_wall",cat:"his",t:"Mur berliński",
 s:"Strzeżony mur, który w latach 1961–1989 dzielił Berlin na wschodni i zachodni i stał się symbolem zimnej wojny.",
 l:"Po drugiej wojnie światowej Niemcy zostały podzielone, a Berlin rozdzielono na komunistyczny Wschód i demokratyczny Zachód. Przez Berlin uciekało z NRD tak wielu ludzi, że w 1961 roku władze wschodnioniemieckie zbudowały mur, który rozrósł się w silnie strzeżoną granicę z wieżami strażniczymi i pasem pustego terenu. Rodziny i przyjaciele byli rozdzieleni przez dziesięciolecia. Dziewiątego listopada 1989 roku, po pokojowych przemianach w Europie Środkowo-Wschodniej, otwarto przejścia graniczne, a tłumy zaczęły rozbijać mur. Niemcy zjednoczyły się w 1990 roku.",
 x:"W muzeum dotknęliśmy prawdziwego kawałka muru berlińskiego pokrytego graffiti.",
 f:"Do upadku muru przyczyniły się przemiany w całym regionie, w tym w Polsce, gdzie w 1989 roku odbyły się obrady Okrągłego Stołu i częściowo wolne wybory czerwcowe.",
 js:"Mur, który przez prawie trzydzieści lat dzielił miasto Berlin na dwie części.",
 jl:"Przez wiele lat przez środek Berlina w Niemczech biegł wielki mur. Ludzie z jednej strony nie mogli odwiedzać przyjaciół i rodziny po drugiej. W 1989 roku otwarto bramy, a ludzie wspinali się na mur, przytulali i wiwatowali. Wkrótce mur rozebrano.",
 jx:"Dziadek pamięta, jak w telewizji pokazywali ludzi tańczących na murze berlińskim."},
{id:"his_pl_grunwald",cat:"his",only:1,t:"Bitwa pod Grunwaldem",
 s:"Wielka bitwa z 15 lipca 1410 roku, w której wojska polsko-litewskie pokonały zakon krzyżacki.",
 l:"Zakon krzyżacki, który rządził w Prusach, od dawna walczył z Polską i Litwą. Latem 1410 roku król Władysław Jagiełło i wielki książę litewski Witold poprowadzili połączone wojska, w których walczyli też Rusini, Czesi i Tatarzy. Pod Grunwaldem, na polach między wsiami Grunwald, Stębark i Łodwigowo, zadali Krzyżakom ciężką klęskę; zginął wielki mistrz Ulrich von Jungingen. Zamku w Malborku nie udało się jednak zdobyć, a wojnę zakończył w 1411 roku pokój toruński.",
 x:"Co roku w lipcu pod Grunwaldem odbywa się inscenizacja bitwy z udziałem tysięcy rekonstruktorów.",
 f:"Jan Matejko namalował w 1878 roku ogromny obraz „Bitwa pod Grunwaldem”, który dziś można oglądać w Muzeum Narodowym w Warszawie.",
 js:"Słynna bitwa z 1410 roku, w której Polacy i Litwini pokonali Krzyżaków.",
 jl:"Ponad sześćset lat temu polski król Władysław Jagiełło i jego kuzyn Witold z Litwy połączyli siły przeciwko rycerzom zakonu krzyżackiego. Spotkali się na polach pod Grunwaldem. Po długiej bitwie wojska polsko-litewskie zwyciężyły. To jedna z najbardziej znanych bitew w historii Polski.",
 jx:"Na wakacjach oglądaliśmy pod Grunwaldem rycerzy w zbrojach i namioty jak ze średniowiecza."},
/* ---------- MATEMATYKA (+6) ---------- */
{id:"mat_negative_number",cat:"mat",t:"Liczba ujemna",
 s:"Liczba mniejsza od zera, zapisywana ze znakiem minus, na przykład minus pięć.",
 l:"Liczby ujemne leżą na osi liczbowej na lewo od zera. Używamy ich do zapisu temperatury poniżej zera, pięter pod ziemią, debetu na koncie czy głębokości poniżej poziomu morza. Dodanie liczby ujemnej działa jak odejmowanie, a odjęcie liczby ujemnej – jak dodawanie. Iloczyn dwóch liczb ujemnych jest dodatni, co wielu uczniów zaskakuje, ale dzięki temu reguły arytmetyki pozostają spójne.",
 x:"W nocy temperatura spadła do minus ośmiu stopni.",
 f:"W siódmym wieku indyjski matematyk Brahmagupta spisał reguły rachunku na liczbach ujemnych, które nazywał długami, a dodatnie – majątkiem.",
 js:"Liczba mniejsza od zera, jak temperatura w mroźny dzień.",
 jl:"Policz do tyłu: trzy, dwa, jeden, zero. Czy można dalej? Tak! Kolejne liczby to minus jeden, minus dwa i tak dalej. To liczby ujemne. Używamy ich, gdy na dworze jest mróz albo gdy winda zjeżdża do podziemnego garażu.",
 jx:"Na przycisku w windzie było minus jeden, więc zjechaliśmy do garażu."},
{id:"mat_ratio",cat:"mat",t:"Stosunek (proporcja)",
 s:"Sposób porównania dwóch wielkości, który pokazuje, ile razy jedna mieści się w drugiej, zapisywany na przykład jako trzy do jednego.",
 l:"Stosunek mówi o zależności między wielkościami, a nie o ich dokładnych rozmiarach. Jeśli w przepisie na dwie szklanki mąki przypada jedna szklanka cukru, stosunek wynosi dwa do jednego, niezależnie od tego, czy pieczesz małe, czy olbrzymie ciasto. Stosunki można skracać jak ułamki: dwanaście do ośmiu to to samo co trzy do dwóch. Równość dwóch stosunków nazywamy proporcją. Stosunków używa się w skali map i makiet, przy mieszaniu farb czy betonu, w kuchni i przy porównywaniu cen.",
 x:"Mapa ma skalę jeden do pięćdziesięciu tysięcy.",
 f:"Zapis skali mapy, na przykład 1 : 50 000, oznacza, że jeden centymetr na mapie odpowiada pięćdziesięciu tysiącom centymetrów, czyli pół kilometra w terenie.",
 js:"Sposób porównania dwóch ilości, na przykład dwie miarki jednego na każdą miarkę drugiego.",
 jl:"Jeśli robisz sok z jednej szklanki syropu i czterech szklanek wody, stosunek wynosi jeden do czterech. Gdy chcesz więcej soku, zachowujesz ten sam stosunek: dwie szklanki syropu i osiem szklanek wody. Wtedy smakuje tak samo!",
 jx:"Do glutka zmieszaliśmy klej z wodą w stosunku dwa do jednego."},
{id:"mat_angle",cat:"mat",t:"Kąt",
 s:"Miara obrotu między dwiema półprostymi wychodzącymi z jednego punktu, zwykle wyrażana w stopniach.",
 l:"Pełny kąt ma trzysta sześćdziesiąt stopni. Kąt prosty, jak róg zeszytu, ma dziewięćdziesiąt stopni. Kąty mniejsze od prostego nazywamy ostrymi, kąty między dziewięćdziesięcioma a stu osiemdziesięcioma stopniami – rozwartymi, a kąt półpełny, wyglądający jak linia prosta, ma sto osiemdziesiąt stopni. Kąty mierzymy kątomierzem. Suma trzech kątów wewnętrznych każdego trójkąta na płaszczyźnie wynosi zawsze sto osiemdziesiąt stopni.",
 x:"Podjazd wznosi się pod kątem zaledwie pięciu stopni, więc łatwo wjechać na niego wózkiem.",
 f:"Podział pełnego obrotu na trzysta sześćdziesiąt stopni wywodzi się zwykle od starożytnych astronomów babilońskich, którzy liczyli w systemie sześćdziesiątkowym.",
 js:"To, jak bardzo rozchodzą się dwie linie od punktu, w którym się spotykają.",
 jl:"Otwórz lekko książkę: okładki tworzą mały kąt. Otwórz ją szerzej, a kąt się powiększy. Róg kwadratu to specjalny kąt, który nazywamy prostym. Kąty mierzymy w stopniach przezroczystym półkolem, czyli kątomierzem.",
 jx:"Kacper zmierzył kątomierzem kąt rampy dla swojej deskorolki."},
{id:"mat_area_perimeter",cat:"mat",t:"Pole i obwód",
 s:"Pole to wielkość powierzchni, którą zajmuje figura; obwód to łączna długość jej brzegu.",
 l:"Obwód mierzymy w jednostkach długości, na przykład w metrach, i obliczamy go, dodając długości wszystkich boków. Pole mierzymy w jednostkach kwadratowych, na przykład w metrach kwadratowych; pole prostokąta to iloczyn jego długości i szerokości. Te pojęcia łatwo pomylić, ale zachowują się inaczej: dwie działki mogą mieć ten sam obwód i zupełnie różne pola. Obwód jest potrzebny, gdy kupujemy siatkę na płot, a pole – gdy kupujemy wykładzinę.",
 x:"Żeby wiedzieć, ile farby kupić, najpierw obliczyliśmy pole ściany.",
 f:"Spośród wszystkich figur o tym samym obwodzie największe pole ma koło.",
 js:"Pole to ile miejsca jest w środku figury, a obwód to długość drogi dookoła niej.",
 jl:"Wyobraź sobie ogródek. Jeśli obejdziesz go dookoła po brzegu, przejdziesz jego obwód. Jeśli wyłożysz cały ogródek kwadratami trawy, liczba kwadratów to jego pole. Płot to sprawa obwodu, a dywan – pola.",
 jx:"Sznurkiem zmierzyliśmy obwód ławki w klasie."},
{id:"mat_polygon",cat:"mat",t:"Wielokąt",
 s:"Płaska figura ograniczona odcinkami połączonymi koniec z końcem w zamkniętą łamaną.",
 l:"Trójkąty, kwadraty, pięciokąty i sześciokąty to wielokąty. Nazywamy je od liczby boków: pięciokąt ma pięć, sześciokąt sześć, a ośmiokąt osiem. Wielokąt foremny ma wszystkie boki i wszystkie kąty równe, jak znak drogowy „stop”. Koło nie jest wielokątem, bo nie ma prostych boków. Wielokąty są wszędzie – od płytek podłogowych i znaków drogowych po malutkie trójkąty, z których zbudowane są kształty w grach komputerowych.",
 x:"Piłka jest pokryta czarnymi pięciokątami i białymi sześciokątami – wszystko to wielokąty.",
 f:"Pszczoły budują sześciokątne komórki, bo sześciokąty przylegają do siebie bez szczelin i zużywają mało wosku.",
 js:"Płaska figura z prostymi bokami, jak trójkąt albo kwadrat.",
 jl:"Wielokąt to każda zamknięta figura zbudowana tylko z prostych kresek. Trójkąt ma trzy boki, kwadrat cztery, a sześciokąt – taki jak komórki w ulu – sześć. Koło nie jest wielokątem, bo jest okrągłe i nie ma prostych boków.",
 jx:"Nina narysowała wielokąty w zeszycie w kratkę i każdy pokolorowała inaczej."},
{id:"mat_rounding",cat:"mat",t:"Zaokrąglanie",
 s:"Zastępowanie liczby prostszą liczbą, która jest jej bliska, na przykład do pełnych dziesiątek.",
 l:"Zaokrąglamy liczby, żeby łatwiej je wymówić, zapamiętać albo szacować. Przy zaokrąglaniu do dziesiątek patrzymy na cyfrę jedności: jeśli to pięć lub więcej, zaokrąglamy w górę, a jeśli mniej niż pięć – w dół. Czterdzieści siedem to po zaokrągleniu pięćdziesiąt, a czterdzieści trzy – czterdzieści. Zaokrągla się ceny, odległości i wyniki pomiarów. To przydatne przy szybkim sprawdzaniu w pamięci, ale w długich obliczeniach małe błędy zaokrągleń mogą się sumować.",
 x:"Rachunek wynosił 19,80 zł, więc w pamięci zaokrągliłam go do dwudziestu złotych.",
 f:"Komputery i księgowi stosują czasem zasadę zaokrąglania połówek do liczby parzystej, tak że na przykład dwa i pół zaokrągla się do dwóch, co zapobiega stałemu zawyżaniu sum.",
 js:"Zamiana liczby na pobliską, łatwiejszą, na przykład 49 na 50.",
 jl:"Jeśli coś kosztuje dziewięćdziesiąt osiem groszy, możesz powiedzieć, że kosztuje około złotówki. To zaokrąglanie: wybierasz ładną, łatwą liczbę, która jest bardzo blisko prawdziwej. Dzięki temu szybko zgadujesz wyniki w głowie.",
 jx:"Na urodzinach było 48 dzieci, więc kupując kubeczki, zaokrągliliśmy to do 50."},
/* ---------- ARCHEOLOGIA (+6) ---------- */
{id:"arc_tell",cat:"arc",t:"Tell",
 s:"Sztuczne wzgórze utworzone z pozostałości osady, którą przez wiele stuleci odbudowywano w tym samym miejscu.",
 l:"W części Bliskiego Wschodu i południowo-wschodniej Europy domy budowano często z cegły mułowej. Gdy stare domy się rozpadały, ludzie wyrównywali gruz i stawiali nowe na wierzchu, więc teren powoli się podnosił. Po tysiącach lat powstawał pagórek pełen warstw, z których każda pochodzi z innego okresu. Archeolodzy kopią w tellach, by odczytać tę historię od góry do dołu – najstarsze warstwy leżą na samym spodzie. Telle są częste w Turcji, Syrii, Iraku, Izraelu i na Bałkanach.",
 x:"Wioska leży obok tellu, na którym ludzie mieszkali przez prawie trzy tysiące lat.",
 f:"Stanowisko starożytnej Troi, Hisarlik w Turcji, to tell z wieloma warstwami miast zbudowanych jedno na drugim.",
 js:"Wzgórze, które powstało, bo ludzie przez bardzo długi czas budowali nowe domy na starych.",
 jl:"Wyobraź sobie, że budujesz z piasku miasteczko, potem na nim nowe, i jeszcze jedno, i jeszcze. Po długim czasie powstałby mały pagórek. W niektórych krajach ludzie robili tak z prawdziwymi domami z gliny przez tysiące lat. Takie wzgórza nazywamy tellami.",
 jx:"Przewodnik powiedział, że wzgórze pod naszymi stopami to tell pełen dawnych domów."},
{id:"arc_midden",cat:"arc",t:"Śmietnisko (kuchenne)",
 s:"Dawne wysypisko odpadków, które archeolodzy badają, by dowiedzieć się, co ludzie jedli, czego używali i co wyrzucali.",
 l:"W śmietniskach można znaleźć muszle, kości zwierząt, skorupy naczyń, popiół, narzędzia i resztki jedzenia. Ponieważ narastały stopniowo, często mają wyraźne warstwy, które pokazują, jak zmieniało się życie. Śmietniska z muszli na wybrzeżach bywają olbrzymie – tworzą je miliony muszli pozostawionych przez kolejne pokolenia. Śmieci opowiadają szczerą historię: pokazują codzienną dietę i zwyczaje zwykłych ludzi, o których rzadko piszą dawne źródła.",
 x:"Zespół przesiał ziemię ze śmietniska i znalazł ości ryb oraz kościany grzebień.",
 f:"Archeolodzy często używają duńskiego terminu kjøkkenmødding, czyli śmietnisko kuchenne, bo pierwsze takie stosy muszli badano w Danii w dziewiętnastym wieku.",
 js:"Bardzo stara kupka śmieci, dzięki której archeolodzy poznają przeszłość.",
 jl:"Pomyśl, co twoja rodzina wyrzuca w ciągu tygodnia: obierki, zepsute rzeczy, butelki. Dawniej ludzie też mieli swoje śmietniska. Archeolodzy je uwielbiają, bo stare muszle, kości i skorupy pokazują, co ludzie na co dzień jedli i czego używali.",
 jx:"Pani zażartowała, że kiedyś archeolodzy będą badać nasze szkolne kosze jak dawne śmietnisko."},
{id:"arc_knapping",cat:"arc",t:"Krzemieniarstwo (łupanie krzemienia)",
 s:"Wytwarzanie narzędzi z krzemienia lub obsydianu przez odbijanie od bryły kamienia kolejnych odłupków.",
 l:"Krzemień i podobne skały pękają gładko, wzdłuż zakrzywionych powierzchni, zostawiając bardzo ostre krawędzie. Dawni ludzie uderzali w rdzeń tłukiem kamiennym, porożem lub kością, by odbić odłupki, a potem używali ich lub dalej obrabiali na noże, drapacze, siekiery i groty strzał. Odpadki z obróbki są częstym znaleziskiem i pokazują, gdzie powstawały narzędzia. Archeolodzy eksperymentalni ćwiczą tę technikę również dziś, ale potrzebne są okulary ochronne, bo odłupki odlatują z dużą prędkością.",
 x:"Na warsztatach w muzeum rzemieślnik w kilka minut zrobił z krzemienia ostre ostrze.",
 f:"Świeżo odłupana krawędź obsydianu może być cieńsza niż ostrze stalowego skalpela.",
 js:"Ostrożne uderzanie w kamienie, żeby zrobić ostre narzędzia, jak w epoce kamienia.",
 jl:"W epoce kamienia nie było metalu. Ludzie robili noże i groty strzał, stukając jednym kamieniem w drugi, tak żeby odpadały ostre kawałki. Ta umiejętność to łupanie krzemienia. Do dziś specjaliści ją ćwiczą, żeby zrozumieć, jak radzili sobie nasi przodkowie.",
 jx:"Oglądaliśmy film, na którym kawałek krzemienia zamienił się w grot strzały."},
{id:"arc_amphora",cat:"arc",t:"Amfora",
 s:"Wysokie gliniane naczynie z dwoma uchwytami i wąską szyjką, w którym w starożytności przewożono wino, oliwę i inne towary.",
 l:"Amfory były kontenerami starożytnego świata. Ich spiczaste dna można było wbić w piasek albo układać warstwami w ładowni statku. W różnych regionach wytwarzano amfory o różnych kształtach, a wiele z nich ma stemple lub malowane napisy, więc archeolodzy potrafią ustalić, gdzie amforę zrobiono i co w niej przewożono. Wraki pełne amfor pomagają odtworzyć dawne szlaki handlowe na Morzu Śródziemnym.",
 x:"Nurkowie znaleźli na dnie morza obok wraku kilkadziesiąt amfor.",
 f:"Monte Testaccio w Rzymie to sztuczne wzgórze usypane niemal w całości ze skorup rzymskich amfor po oliwie.",
 js:"Duży gliniany dzban z dwoma uchwytami, w którym dawniej przewożono oliwę i wino.",
 jl:"W starożytnej Grecji i Rzymie nie było plastikowych butelek ani kartonów. Oliwę, wino i sos rybny przewożono w wysokich glinianych dzbanach z dwoma uchwytami i spiczastym dnem. To amfory. Statki wiozły ich naraz setki.",
 jx:"Ela zrobiła amforę z papieru i namalowała na niej greckie wzory."},
{id:"arc_tutankhamun",cat:"arc",t:"Grobowiec Tutanchamona",
 s:"Miejsce pochówku młodego egipskiego faraona, odkryte niemal nienaruszone w Dolinie Królów w 1922 roku.",
 l:"Tutanchamon panował w Egipcie około dziesięciu lat w czternastym wieku przed naszą erą i zmarł młodo. Jego niewielki grobowiec przykrył gruz z późniejszych budów, więc uniknął większości grabieży, które ogołociły inne grobowce królewskie. W listopadzie 1922 roku archeolog Howard Carter, finansowany przez lorda Carnarvona, odnalazł jego wejście. W środku były złocone kaplice, rydwany, biżuteria, meble i słynna złota maska. Staranne opisanie i wydobycie przedmiotów zajęło około dziesięciu lat.",
 x:"Złota maska z grobowca Tutanchamona to jeden z najsłynniejszych zabytków świata.",
 f:"W grobowcu znajdowało się ponad pięć tysięcy przedmiotów – od złotych tronów po koszyki z owocami i sandały.",
 js:"Pełen skarbów grobowiec młodego króla Egiptu, odkryty około stu lat temu.",
 jl:"Tutanchamon był królem starożytnego Egiptu, który został faraonem jako dziecko. Ponad trzy tysiące lat później archeolog odnalazł jego grobowiec, wciąż pełen skarbów: złotych mebli, klejnotów i pięknej złotej maski.",
 jx:"Sara zbudowała z klocków grobowiec Tutanchamona ze złotą maską w środku."},
{id:"arc_fieldwalking",cat:"arc",t:"Badania powierzchniowe",
 s:"Metoda poszukiwań, w której archeolodzy przechodzą zaoranym polem w równych rzędach, zbierając i zapisując przedmioty leżące na powierzchni.",
 l:"Orka wydobywa na powierzchnię skorupy naczyń, krzemienie, dachówki i inne drobne zabytki z ukrytych stanowisk. Podczas badań powierzchniowych zespół idzie powoli w równo rozstawionych rzędach i pakuje każde znalezisko, zapisując dokładnie, gdzie je podniósł. Gdy zaznaczy się je na mapie, skupiska mogą wskazać ukryte osady, pracownie czy drogi bez kopania. W Polsce prowadzono w ten sposób wielki program Archeologiczne Zdjęcie Polski. Na poszukiwania potrzebna jest zgoda właściciela terenu, a w Polsce także pozwolenie konserwatora zabytków.",
 x:"Po jesiennej orce archeolodzy przeszli pole i zebrali skorupy z czasów rzymskich.",
 f:"Najlepiej prowadzić je po deszczu, który spłukuje ziemię z zabytków, więc skorupy i krzemienie lepiej widać na powierzchni.",
 js:"Powolne chodzenie po polu i szukanie starych przedmiotów leżących na ziemi.",
 jl:"Kiedy rolnik zaorze pole, na wierzch mogą wyjść kawałki starych garnków i kamienne narzędzia. Archeolodzy chodzą wtedy po polu w prostych rzędach, zbierają to, co widzą, i zapisują, gdzie to było. Potem mogą zgadnąć, gdzie dawno temu mieszkali ludzie.",
 jx:"Z panią z muzeum chodziliśmy po polu i znaleźliśmy kawałek bardzo starego garnka."},
/* ---------- KUCHNIA (+6) ---------- */
{id:"cook_kneading",cat:"cook",t:"Wyrabianie ciasta",
 s:"Ugniatanie, składanie i rozciąganie ciasta, aż stanie się gładkie i elastyczne.",
 l:"Wyrabianie rozwija gluten, czyli sieć białek z mąki pszennej, która zatrzymuje gaz i pomaga chlebowi wyrosnąć i zachować kształt. Ręcznie odpycha się ciasto nasadą dłoni, składa je z powrotem i obraca, powtarzając to przez kilka minut. Na początku ciasto jest grudkowate i klejące, potem robi się gładkie i sprężyste. Ciast biszkoptowych i kruchych prawie się nie wyrabia, bo mocna sieć glutenu zrobiłaby je twardymi.",
 x:"Po dziesięciu minutach wyrabiania ciasto było gładkie i odbijało, gdy je nacisnęłam palcem.",
 f:"Niektóre chleby prawie nie wymagają wyrabiania: mokre ciasto zostawione na wiele godzin samo powoli rozwija gluten.",
 js:"Ugniatanie ciasta rękami, żeby upiec chleb.",
 jl:"Żeby zrobić chleb, gniecie się ciasto rękami, składa je, obraca i gniecie znowu. To wyrabianie. Trochę przypomina zabawę ciastoliną. Dzięki temu ciasto robi się rozciągliwe, a chleb może wyrosnąć wysoki i puszysty.",
 jx:"Wyrabianie ciasta na pizzę było moją ulubioną częścią warsztatów kulinarnych."},
{id:"cook_poaching",cat:"cook",t:"Gotowanie w płynie poniżej wrzenia (poszowanie)",
 s:"Delikatne gotowanie jedzenia w płynie, który jest gorący, ale wyraźnie poniżej temperatury wrzenia.",
 l:"Przy poszowaniu płyn prawie się nie porusza, pojawiają się w nim tylko pojedyncze małe pęcherzyki. Takie łagodne ciepło służy delikatnym produktom, które w bulgoczącej wodzie by się rozpadły albo stwardniały: jajkom, rybom, piersi kurczaka i owocom. Płynem może być woda, wywar, mleko albo wino, doprawione ziołami lub przyprawami. Poszowanie nie wymaga tłuszczu, więc jest lekką metodą, a płyn często można potem zamienić w sos.",
 x:"Na śniadanie przygotował dwa jajka w koszulce i podał je na grzance.",
 f:"Jajko poszowane po polsku nazywamy jajkiem w koszulce, bo białko otula żółtko jak cienka koszulka.",
 js:"Delikatne gotowanie w gorącej wodzie, która nie bulgocze mocno.",
 jl:"Niektóre jedzenie jest delikatne, na przykład jajka czy ryby. W mocno bulgoczącej wodzie by się rozpadły. Można je więc włożyć do wody bardzo gorącej, ale tylko lekko parującej. Tak przygotowuje się na przykład jajko w koszulce.",
 jx:"Mama ugotowała gruszki w soku jabłkowym na ciepły deser."},
{id:"cook_steaming",cat:"cook",t:"Gotowanie na parze",
 s:"Przygotowywanie jedzenia w gorącej parze unoszącej się nad wrzącą wodą, bez kontaktu z wodą.",
 l:"Jedzenie układa się w koszyczku lub na kratce nad gotującą się wodą i przykrywa pokrywką. Gotowanie na parze jest delikatne i nie wysusza potraw, a warzywa tracą mniej witamin niż przy gotowaniu w wodzie, bo mniej ich do niej przechodzi. To podstawa wielu kuchni: chińskie pierożki i bułeczki gotuje się w piętrowych bambusowych koszyczkach. Przy zdejmowaniu pokrywki trzeba uważać, bo para parzy.",
 x:"Brokuły gotowaliśmy na parze cztery minuty, więc zostały jasnozielone.",
 f:"Para może poparzyć mocniej niż wrząca woda o tej samej temperaturze, bo skraplając się na skórze, oddaje dużo dodatkowego ciepła.",
 js:"Gotowanie jedzenia w gorącej chmurce, która unosi się nad wrzącą wodą.",
 jl:"Kiedy woda się gotuje, powstaje gorąca chmurka, czyli para. Jeśli położysz jedzenie w koszyczku nad wodą i zamkniesz pokrywkę, para je ugotuje. Warzywa z pary są kolorowe i chrupkie. Pokrywkę zawsze niech podnosi dorosły, bo para jest bardzo gorąca.",
 jx:"W restauracji pierożki przyniesiono w małym bambusowym koszyczku do gotowania na parze."},
{id:"cook_zest",cat:"cook",t:"Skórka cytrusowa",
 s:"Cienka, kolorowa zewnętrzna warstwa skórki cytrusów, ścierana lub obierana dla aromatu.",
 l:"Skórka cytryn, limonek i pomarańczy zawiera maleńkie zbiorniczki pachnącego olejku, które nadają świeży, wyrazisty smak ciastom, sosom, marynatom i napojom. Używa się tylko kolorowej warstwy – biała część pod spodem, zwana albedo, jest gorzka. Skórkę zdejmuje się drobną tarką, specjalnym skrobakiem albo obieraczką. Owoce przeznaczone na skórkę warto dokładnie umyć, a wielu kucharzy wybiera owoce niewoskowane.",
 x:"Do ciasta na babeczki dodała startą skórkę z jednej cytryny.",
 f:"Kandyzowana skórka pomarańczowa to tradycyjny dodatek do polskich wypieków świątecznych, na przykład do keksu i makowca.",
 js:"Cienka, kolorowa skórka cytryny albo pomarańczy, ścierana dla smaku.",
 jl:"Potrzyj skórkę cytryny i powąchaj palce: pachną cudownie! Ten zapach pochodzi z olejku w cienkiej, żółtej warstwie na wierzchu. Kucharze ścierają ją do ciast i sosów. Białą część pod spodem zostawiają, bo jest gorzka.",
 jx:"Starłam skórkę pomarańczy na naleśniki i cała kuchnia pięknie pachniała."},
{id:"cook_baking_blind",cat:"cook",t:"Pieczenie na ślepo",
 s:"Podpiekanie samego spodu z ciasta, zanim doda się nadzienie.",
 l:"Wilgotne nadzienia, takie jak krem czy masa jajeczna do quiche, mogą rozmoczyć ciasto, jeśli oba trafią do piekarnika surowe. Żeby temu zapobiec, wyłożony ciastem spód przykrywa się papierem do pieczenia i obciąża ceramicznymi kulkami, suchą fasolą albo ryżem, by ciasto nie wybrzuszyło się ani nie zsunęło z boków, a potem piecze, aż się zetnie. Następnie zdejmuje się obciążenie i papier i zwykle dopieka spód, aż będzie suchy i lekko złoty, zanim się go napełni.",
 x:"Przepis każe piec spód tarty na ślepo przez piętnaście minut, zanim wleje się masę cytrynową.",
 f:"Fasoli używanej do pieczenia na ślepo nie da się potem zjeść, ale po wystygnięciu można jej używać do tego samego celu wiele razy.",
 js:"Pieczenie pustego spodu z ciasta, zanim włoży się nadzienie.",
 jl:"Niektóre tarty mają płynne nadzienie, przez które ciasto zrobiłoby się miękkie i rozmoczone. Dlatego cukiernicy najpierw pieką pusty spód, przyciśnięty suchą fasolą, żeby trzymał kształt. Dopiero potem wlewają nadzienie. Ten sposób nazywa się pieczeniem na ślepo.",
 jx:"Babcia pokazała mi, jak piec spód tarty na ślepo ze słoikiem starej fasoli."},
{id:"cook_pl_oscypek",cat:"cook",only:1,t:"Oscypek",
 s:"Wędzony ser z mleka owczego z Podhala, w kształcie wrzeciona, zdobiony wzorami z drewnianej formy.",
 l:"Oscypek robią bacowie w bacówkach na halach. Mleko owcze, czasem z dodatkiem krowiego, zagęszcza się podpuszczką, a powstały ser wielokrotnie parzy w gorącej wodzie i ugniata. Masę wciska się do rzeźbionych drewnianych foremek, które odciskają na serze ozdobne wzory, a potem moczy w solance i wędzi w dymie. Prawdziwy oscypek powstaje sezonowo, w czasie wypasu owiec od wiosny do jesieni. Na Podhalu je się go także na ciepło, z grilla, z żurawiną.",
 x:"Na Krupówkach kupiliśmy grillowanego oscypka z żurawiną.",
 f:"Od 2008 roku nazwa oscypek jest w Unii Europejskiej chroniona jako Chroniona Nazwa Pochodzenia, więc tak może się nazywać tylko ser zrobiony na Podhalu według tradycyjnej receptury.",
 js:"Wędzony ser z owczego mleka, robiony w górach na Podhalu.",
 jl:"Oscypek to ser z gór. Robią go bacowie z mleka owiec, które pasą się na halach. Ser wciska się do drewnianych foremek z wzorkami, a potem wędzi w dymie, dzięki czemu robi się złotobrązowy i pachnący. Najlepiej smakuje z żurawiną.",
 jx:"W Zakopanem Tymek zjadł ciepłego oscypka i poprosił o jeszcze jednego."},
/* ---------- SZTUKA (+6) ---------- */
{id:"art_landscape",cat:"art",t:"Pejzaż",
 s:"Obraz, którego głównym tematem jest krajobraz: góry, pola, rzeki czy niebo.",
 l:"Przez stulecia krajobraz był głównie tłem obrazów o tematyce religijnej i historycznej. W siedemnastym wieku malarze holenderscy uczynili z niego osobny temat, z rozległym niebem i płaskimi równinami. Później artyści tacy jak Anglicy John Constable i William Turner oraz francuscy impresjoniści malowali w plenerze, by uchwycić zmienne światło i pogodę. W Polsce pejzaże malowali między innymi Józef Chełmoński i Jan Stanisławski. Pejzaż może być realistyczny, baśniowy albo prawie abstrakcyjny i często oddaje nastrój tak samo jak miejsce.",
 x:"W sali pejzaży w galerii wiszą wzburzone morza i zamglone góry.",
 f:"Słowo pejzaż pochodzi od francuskiego paysage, utworzonego od słowa pays, czyli kraj lub okolica.",
 js:"Obraz przyrody, na przykład wzgórz, drzew, rzek i nieba.",
 jl:"Pejzaż to obraz, na którym widać przyrodę: las, plażę, góry albo łąkę pełną kwiatów. Niektórzy malarze wynoszą farby na dwór i malują to, co widzą, podczas gdy światło i chmury się zmieniają.",
 jx:"Na zadanie domowe Tymon namalował pejzaż parku z wielkim pomarańczowym zachodem słońca."},
{id:"art_sketch",cat:"art",t:"Szkic",
 s:"Szybki, roboczy rysunek, który uchwyca główną myśl albo kształt czegoś.",
 l:"Artyści szkicują, by sprawdzić pomysły, ćwiczyć, zanotować to, co widzą, i zaplanować większe dzieła. Szkic powstaje zwykle ołówkiem, węglem albo piórem, bez dbania o szczegóły i idealne linie. Szkicowniki słynnych artystów są bardzo cenne, bo pokazują, jak rozwijały się ich pomysły. Szkicują też projektanci, architekci i inżynierowie, a w szerszym znaczeniu szkicem nazywamy każdą krótką, wstępną wersję czegoś, na przykład zarys wypracowania.",
 x:"Zanim namalowała mural, zapełniła szkicami trzy strony.",
 f:"Słowo szkic trafiło do polszczyzny z niemieckiego Skizze, które pochodzi od włoskiego schizzo, czyli bryzg albo szybki rysunek.",
 js:"Szybki rysunek, który nie musi być idealny.",
 jl:"Szkic to szybki rysunek, który pokazuje najważniejsze kształty. Nie trzeba gumkować błędów ani rysować każdego szczegółu. Artyści robią mnóstwo szkiców, żeby wypróbować pomysły, zanim zaczną duży obraz.",
 jx:"Ada nosi w plecaku szkicownik i rysuje psy, które widzi w parku."},
{id:"art_sculpture",cat:"art",t:"Rzeźba",
 s:"Sztuka trójwymiarowa, tworzona przez kucie, modelowanie, odlewanie albo łączenie materiałów.",
 l:"Rzeźbiarze pracują na wiele sposobów. Mogą odkuwać kamień lub wycinać drewno, modelować miękką glinę lub wosk, odlewać metal, na przykład brąz, w formie albo łączyć znalezione przedmioty. Rzeźbę wolnostojącą można obejść i oglądać z każdej strony, a płaskorzeźba wystaje z płaskiego tła, jak wizerunek na monecie. Rzeźba współczesna obejmuje także instalacje, ruchome obiekty i prace ze światła, dźwięku, a nawet lodu.",
 x:"W parku stoi rzeźba z brązu przedstawiająca dziewczynkę czytającą książkę.",
 f:"Wiele rzeźb z brązu powstaje metodą traconego wosku: woskowy model pokrywa się formą, wytapia wosk, a w puste miejsce wlewa roztopiony brąz.",
 js:"Sztuka, którą można obejść dookoła, na przykład posąg z kamienia, gliny albo metalu.",
 jl:"Obraz jest płaski, a rzeźba ma wysokość, szerokość i głębokość, tak jak prawdziwe przedmioty. Rzeźbiarze kują w kamieniu, lepią z gliny albo wlewają gorący metal do form. Rzeźbę można obejść i obejrzeć z każdej strony.",
 jx:"Ulepiliśmy z gliny rzeźby naszych zwierzaków i wypaliliśmy je w szkolnym piecu."},
{id:"art_baroque",cat:"art",t:"Barok",
 s:"Dramatyczny, bogato zdobiony styl w sztuce, architekturze i muzyce siedemnastego i początku osiemnastego wieku.",
 l:"Sztuka barokowa chce poruszyć uczucia widza. Obrazy mają silne kontrasty światła i cienia, wirujący ruch i chwile pełne napięcia, a kościoły i pałace lśnią złoceniami, krzywiznami, malowanymi sklepieniami i rzeźbami, które jakby wychodzą ze ścian. Styl narodził się w Rzymie i rozprzestrzenił w katolickiej Europie i poza nią. Do słynnych twórców baroku należą Caravaggio, Bernini i Rubens, a w muzyce Bach, Vivaldi i Händel. W Polsce przykładem jest pałac w Wilanowie.",
 x:"Sklepienie barokowego kościoła namalowano tak, że niebo zdaje się otwierać nad głową.",
 f:"Nazwę barok wywodzi się często od portugalskiego słowa oznaczającego perłę o nieregularnym kształcie; początkowo była to obelga dla sztuki, która wydawała się zbyt dziwna i przesadna.",
 js:"Bardzo strojny, dramatyczny styl sprzed około czterystu lat, z mnóstwem złota i zawijasów.",
 jl:"Sztuka barokowa jest jak wielkie przedstawienie. Kościoły i pałace w tym stylu mają złote ozdoby, kręcone kształty i sufity pomalowane w chmury i latające postacie. Obrazy są pełne ruchu i mocnego światła, jakby właśnie działo się coś ekscytującego.",
 jx:"W pałacu w Wilanowie każda sala miała złote ozdoby i malowane sufity."},
{id:"art_pop_art",cat:"art",t:"Pop-art",
 s:"Kierunek w sztuce lat pięćdziesiątych i sześćdziesiątych dwudziestego wieku, który sięgał po obrazy z reklam, komiksów i codziennych produktów.",
 l:"Pop-art narodził się w Wielkiej Brytanii i Stanach Zjednoczonych jako reakcja na poważną sztukę abstrakcyjną. Artyści brali motywy z kultury popularnej – puszki zupy, gwiazdy filmowe, komiksy i reklamy – i pokazywali je w galeriach, często w jaskrawych, płaskich kolorach i technikach zapożyczonych z druku. Jedni świętowali nowoczesne życie konsumpcyjne, inni łagodnie z niego kpili. Do znanych twórców pop-artu należą Andy Warhol, Roy Lichtenstein oraz Brytyjczycy Richard Hamilton i Peter Blake.",
 x:"Plakat w jej pokoju wygląda jak pop-art, z jaskrawymi kropkami i dymkiem jak z komiksu.",
 f:"W 1962 roku Andy Warhol pokazał trzydzieści dwa obrazy przedstawiające puszki zupy Campbell, po jednym na każdy smak, który firma wtedy sprzedawała.",
 js:"Jaskrawa, wyrazista sztuka z obrazkami z komiksów, reklam i sklepowych produktów.",
 jl:"Artyści pop-artu przyglądali się rzeczom, które każdy zna – kreskówkom, papierkom po cukierkach i puszkom zupy – i zamieniali je w sztukę. Ich obrazy są często jaskrawe, z mocnymi kolorami i czarnymi konturami, trochę jak olbrzymi komiks.",
 jx:"Na plastyce zrobiliśmy obrazki w stylu pop-artu z naszymi ulubionymi przekąskami."},
{id:"art_pl_dama_z_gronostajem",cat:"art",only:1,t:"Dama z gronostajem",
 s:"Portret pędzla Leonarda da Vinci, najcenniejszy obraz w polskich zbiorach, przechowywany w Krakowie.",
 l:"Leonardo namalował ten portret około 1489–1491 roku w Mediolanie. Przedstawia młodą Cecylię Gallerani, która trzyma w ramionach białe zwierzę – gronostaja. Obraz zachwyca tym, jak dziewczyna odwraca głowę, jakby ktoś ją zawołał, i jak delikatnie oddano dłoń oraz futro zwierzęcia. Na przełomie osiemnastego i dziewiętnastego wieku kupił go książę Adam Jerzy Czartoryski, a obraz stał się ozdobą rodzinnej kolekcji. W 2016 roku państwo polskie kupiło zbiory Czartoryskich, a dzieło można oglądać w Muzeum Książąt Czartoryskich w Krakowie.",
 x:"Na szkolnej wycieczce do Krakowa staliśmy w kolejce, żeby zobaczyć Damę z gronostajem.",
 f:"To jeden z zaledwie czterech zachowanych portretów kobiet namalowanych przez Leonarda da Vinci; inny to Mona Lisa.",
 js:"Słynny obraz Leonarda da Vinci, który można zobaczyć w Krakowie.",
 jl:"Dama z gronostajem to portret młodej kobiety, która trzyma na rękach białe, puszyste zwierzątko – gronostaja. Namalował go ponad pięćset lat temu sławny Leonardo da Vinci. Obraz jest w Polsce, w muzeum w Krakowie.",
 jx:"Po wizycie w muzeum Hania narysowała swoją kotkę tak, jakby była gronostajem z obrazu."}
]);
